Batch.Body:
#
# Add a new protection group name and description to VBR using pre-existing VBR credentials
# indexed by username and user description for the agent target(s) passed to the script.
#
# Inputs: existing managed credentials for the target computers referenced by "agentusername"
# and  "agentcredentialdesc", protection group name "protectiongroupname", protection group 
# description "protectiongroupdesc" and host(s) to add to the protection group "agenttargets"
#
try {
    $cred = Get-VBRCredentials | Where-Object {$_.Description -eq "{{.global.task.input.agentcredentialdesc}}" -and $_.Name -eq "{{.global.task.input.agentusername}}"}
    if ($cred -ne $null) {
        $customCredsArray = @()
        $ICOcollection = "{{.global.task.input.agenttargets}}".SubString(1, "{{.global.task.input.agenttargets}}".Length-2)
        $hostsArray = $ICOcollection -Split " "

        $computers = $hostsArray | ForEach { New-VBRIndividualComputerCustomCredentials -HostName $_ -Credentials $cred }

        $protContainer = New-VBRIndividualComputerContainer -CustomCredentials $computers

        $protGroup = Add-VBRProtectionGroup -Name "{{.global.task.input.protectiongroupname}}" -Container $protContainer -Description "{{.global.task.input.protectiongroupdesc}}"

        $deploymentOpt = New-VBRProtectionGroupDeploymentOptions -InstallAgent -UpgradeAutomatically -RebootIfRequired

        Set-VBRProtectionGroup -ProtectionGroup $protGroup -DeploymentOptions $deploymentOpt

        Rescan-VBREntity -Entity $protGroup   
    }
    else {
        Write-Error "Credentials not found!"
        exit 1
    }
    exit 0
}
catch {
    Write-Error "Exception in add protection group"
    exit 1
}

#
# Search VBR managed credentials for a matching username / user description. If found return
# true otherwise create a new set of credentials and return true if the credentials were 
# successfully created.
#
# Inputs: workflow inputs with referenced inputs "username", "userdescription", "userpassword"
# and "accounttype" (0 - "Windows" default or 1 - "Linux")
#
try {
    $cred = Get-VBRCredentials | Where-Object {$_.Description -eq "{{.global.task.input.userdescription}}" -and $_.Name -eq "{{.global.task.input.username}}"}
    if ($cred -EQ $null) {
        if ({{.global.task.input.accounttype}} -EQ 1) {
            $cred = Add-VBRCredentials -User "{{.global.task.input.username}}" -Password "{{.global.task.input.userpassword}}" -Description "{{.global.task.input.userdescription}}" -Type "Linux" -ElevateToRoot
        }
        else {
            $cred = Add-VBRCredentials -User "{{.global.task.input.username}}" -Password "{{.global.task.input.userpassword}}" -Description "{{.global.task.input.userdescription}}" -Type "Windows"
        }
        if ($cred -EQ $null) { exit 1 }
    }
    exit 0
}
catch { exit 1 }

#
# Add a new managed server to VBR with the pre-existing credentials (indexed by username and
# user description).  If the managed server already exists or if the specified credentials
# do not exist an error is returned otherwise the new managed server is created per the 
# platform (Windows, Linux) specified.
#
# Inputs: workflow inputs with references "servername", existing managed credentials
# referenced by "username" and  "userdescription" and "hostplatform" (0 - Windows, 1 - Linux)
#
try {
    $managedServer = Get-VBRServer -Name "{{.global.task.input.servername}}"
    if ($managedServer -EQ $null) {
        $cred = Get-VBRCredentials | Where-Object {$_.Description -eq "{{.global.task.input.credentialdesc}}" -and $_.Name -eq "{{.global.task.input.username}}"}
        if ($cred -ne $null) {
            Switch ({{.global.task.input.hostplatform}}) {
                0 {
                    Write-Output "Adding windows host"
                    Add-VBRWinServer -Name "{{.global.task.input.servername}}" -Credentials $cred
                    }
                1 {        
                    Write-Output "Adding linux host"
                    Add-VBRLinux -Name "{{.global.task.input.servername}}" -Credentials $cred -confirm:$False
                    }
            }
        }
        else {
            Write-Error -Message "Credentials not found!"
            exit 1
        }
    }
    else {
        Write-Error -Message "Managed server already exists"
        exit 0
    }
    exit 0
}
catch { 
    Write-Output "Exception in add managed server" 
    exit 1 
}

#
# Add a new proxy from an existing managed server to VBR.  If the managed server does not
# already exist an error is returned otherwise the managed server is assigned the specified
# proxy type role assuming it is appropriate to the platform (i.e. no Linux support for 
# Hyper-V proxy).
#
# Inputs: workflow inputs with references "servername" and "proxytype" (0 - VMware/Windows,
# 1 - VMware/Linux, 2 - HyperV, 3 - NAS, 4 - CDP, 5 - Computer)
try {
    $managedServer = Get-VBRServer -Name {{.global.task.input.servername}}
    if ($managedServer -NE $null) {
        Switch ({{.global.task.input.proxytype}}) {
            0   {
                Write-Host "Adding Windows VMWare proxy"
                Add-VBRViProxy -Server {{.global.task.input.servername}}
                }
            1   {
                Write-Host "Adding Linux VMWare proxy"
                Add-VBRViLinuxProxy -Server {{.global.task.input.servername}}
                }
            2   {
                Write-Host "Adding HyperV proxy"
                Add-VBRHvProxy -Server {{.global.task.input.servername}}
                }
            3   {
                Write-Host "Adding NAS proxy"
                Add-VBRNASProxyServer -Server {{.global.task.input.servername}}
                }
            4   {
                Write-Host "Adding CDP proxy"
                Add-VBRCDPProxy -Server {{.global.task.input.servername}}
                }                
            5   {
                Write-Host "Adding Computer proxy"
                Add-VBRComputerFileProxyServer -Server {{.global.task.input.servername}}
                }
           default {
                Write-Host "Proxy type not supported!"
                exit 1
            }
        }
        exit 0 
    }
    else {
        Write-Output "Managed server not found!"
        exit 0
    }
}
catch {
    Write-Output "Exception in add proxy"
    exit 1
}

#
# Search VBR managed credentials for a matching username / user description. If found return
# true otherwise create a new set of credentials and return true if the credentials were 
# successfully created.
#
# Inputs: workflow inputs with referenced inputs "username", "userdescription", "userpassword"
# and "accounttype" (0 - "Windows" default or 1 - "Linux")
#
try {
    $cred = Get-VBRCredentials | Where-Object {$_.Description -eq "{{.global.task.input.userdescription}}" -and $_.Name -eq "{{.global.task.input.username}}"}
    if ($cred -EQ $null) {
        if ({{.global.task.input.accounttype}} -EQ 1) {
            $cred = Add-VBRCredentials -User "{{.global.task.input.username}}" -Password "{{.global.task.input.userpassword}}" -Description "{{.global.task.input.userdescription}}" -Type "Linux" -ElevateToRoot
        }
        else {
            $cred = Add-VBRCredentials -User "{{.global.task.input.username}}" -Password "{{.global.task.input.userpassword}}" -Description "{{.global.task.input.userdescription}}" -Type "Windows"
        }
        if ($cred -EQ $null) { exit 1 }
    }
    exit 0
}
catch { exit 1 }
